<?php $title='Your cart';require 'includes/header.php';if(!logged()){redirect('auth/login.php');}$s=$pdo->prepare('SELECT c.id,c.quantity,p.* FROM cart_items c JOIN products p ON p.id=c.product_id WHERE c.user_id=?');$s->execute([$_SESSION['user']['id']]);$items=$s->fetchAll();$total=array_sum(array_map(fn($x)=>$x['price']*$x['quantity'],$items)); ?><section class="container section"><div class="sectionHead"><div><span class="eyebrow">YOUR CART</span><h1>Ready to checkout?</h1></div></div><?php if(!$items):?><div class="empty"><div>🛒</div><h2>Your cart is empty</h2><a class="btn primary" href="products.php">Start shopping</a></div><?php else:?><form method="post" action="actions/cart.php"><input type="hidden" name="action" value="update"><div class="cartLayout"><div><?php foreach($items as $x):?><div class="cartRow"><img src="assets/images/<?=e($x['image'])?>"><div><h3><?=e($x['name'])?></h3><small><?=e($x['category'])?></small></div><input class="qty" type="number" min="1" max="20" name="qty[<?=$x['id']?>]" value="<?=$x['quantity']?>"><b>₹<?=number_format($x['price']*$x['quantity'])?></b><button formaction="actions/cart.php" name="action" value="remove" class="iconBtn">×</button><input type="hidden" name="product_id" value="<?=$x['id']?>"></div><?php endforeach;?><button class="btn ghost">Update cart</button></div><aside class="summary"><h2>Order summary</h2><div><span>Subtotal</span><b>₹<?=number_format($total)?></b></div><div><span>Delivery</span><b>FREE</b></div><hr><div class="grand"><span>Total</span><b>₹<?=number_format($total)?></b></div><a class="btn primary full" href="checkout.php">Proceed to checkout</a></aside></div></form><?php endif;?></section><?php require 'includes/footer.php'; ?>